																																																		local n35 = 2

																																																		colorsMatch = function(arg, arg2)
																																																			return math.abs(math.round(arg.R * 255) - math.round(arg2.R * 255)) <= n35 and math.abs(math.round(arg.G * 255) - math.round(arg2.G * 255)) <= n35 and math.abs(math.round(arg.B * 255) - math.round(arg2.B * 255)) <= n35
																																																		end

																																																		isSandColor = function(arg)
																																																			return colorsMatch(arg, color) or colorsMatch(arg, color2) or colorsMatch(arg, color3)
