																																																			end

																																																			table.insert(tbl41[assetId], { index = i, y = v75.cframe.Position.Y })
																																																		end

																																																		for _, v75 in pairs(tbl41) do
																																																			if #v75 > 1 then
																																																				local tbl42 = {}

																																																				for _, v76 in ipairs(v75) do
																																																					local str6 = tostring(math.round(v76.y * 1000))
																																																					tbl42[str6] = (tbl42[str6] or 0) + 1
																																																				end

																																																				local n35 = 0
																																																				local v76 = nil

																																																				for k, v77 in pairs(tbl42) do
																																																					if n35 < v77 then
																																																						n35 = v77
																																																						v76 = k
																																																					end
																																																				end

																																																				local n36 = tonumber(v76) / 1000

																																																				for _, v77 in ipairs(v75) do
																																																					if math.abs(v77.y - n36) > 0.001 then
																																																						local v78 = tbl33[v77.index]
																																																						local cframe2 = v78.cframe
																																																						local position = cframe2.Position
																																																						local v79, v80, v81 = cframe2:ToEulerAnglesXYZ()
																																																						v78.cframe = CFrame.new(position.X, n36, position.Z) * CFrame.fromEulerAnglesXYZ(v79, v80, v81)
																																																					end
																																																				end
																																																			end
																																																		end
																																																	end

